CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon, authenticated, service_role;
CREATE TABLE public.products (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,subtitle text NOT NULL DEFAULT '',category text NOT NULL CHECK(category IN ('Ramen','Chocolate','Beauty')),price numeric NOT NULL CHECK(price>=0),old numeric,size text NOT NULL DEFAULT '',image text NOT NULL,tag text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.products_id_seq TO authenticated,service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public catalogue" ON public.products FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin product writes" ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id),name text NOT NULL DEFAULT 'KUMO',phone text NOT NULL DEFAULT '');
GRANT SELECT ON public.store_settings TO anon;
GRANT SELECT,UPDATE ON public.store_settings TO authenticated;
GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public store settings" ON public.store_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin settings writes" ON public.store_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
